def generate_carp_pattern(n: int) -> None:
    carp = [["#"]]
    for k in range(1, n + 1):
        tmp = []
        for _ in range(3):
            for c in carp:
                tmp.append(c * 3)

        tmp = list(map(list, tmp))

        cen = 3**(k - 1)
        for i in range(3**k):
            for j in range(3**k):
                if i // cen % 3 == 1 and j // cen % 3 == 1:
                    tmp[i][j] = "."
        carp = tmp

    for c in carp:
        print("".join(c))
